const segments=value=>Array.from(new Intl.Segmenter('pt-BR',{granularity:'grapheme'}).segment(String(value||'').normalize('NFC')),x=>x.segment);const abbreviation=value=>segments(String(value||'').trim()).slice(0,3).join('').toLocaleUpperCase('pt-BR');const initials=node=>abbreviation(node?.sigla||node?.name)||'AR';const ink=hex=>{const c=hex.replace('#','');return (parseInt(c.slice(0,2),16)*299+parseInt(c.slice(2,4),16)*587+parseInt(c.slice(4,6),16)*114)/1000>150?'#171717':'#fff'};
