const levels=['Área','Setor','Local','Sublocal'];const colors=['#7c3aed','#eab308','#ef4444','#f97316','#22c55e','#2563eb'];const paths=[icons.groups,icons.overview,icons.team,icons.records,icons.settings,...Object.entries(jobIcons).filter(([id])=>!id.startsWith('custom-')).map(([,svg])=>svg.replace(/^<svg[^>]*>/,'').replace(/<\/svg>$/,'')),...Object.values(icons)];
